import{_ as e}from"./chunks/img.Dck1PxLc.js";import{_ as i,C as a,c as s,o,j as t,G as r,a0 as n,a as l}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"À propos de l&#39;Académie de Pétanque","description":"","frontmatter":{},"headers":[],"relativePath":"fr/about.md","filePath":"fr/about.md"}');const d=i({name:"fr/about.md"},[["render",function(i,u,d,c,p,m){const h=a("AdBanner"),g=a("AdInArticle");return o(),s("div",null,[u[0]||(u[0]=t("h1",{id:"a-propos-de-l-39-academie-de-petanque",tabindex:"-1"},[l("À propos de l'Académie de Pétanque "),t("a",{class:"header-anchor",href:"#a-propos-de-l-39-academie-de-petanque","aria-label":'Permalink to "À propos de l&#39;Académie de Pétanque"'},"​")],-1)),r(h),u[1]||(u[1]=n('<h2 id="une-passion-pour-la-petanque" tabindex="-1">Une passion pour la pétanque <a class="header-anchor" href="#une-passion-pour-la-petanque" aria-label="Permalink to &quot;Une passion pour la pétanque&quot;">​</a></h2><p>Bienvenue à l&#39;Académie de Pétanque, où une véritable passion pour ce sport nous anime depuis plus de 45 ans. Mon parcours avec la pétanque a été marqué par le dévouement, le talent et un enthousiasme constant.</p><p>La pétanque n&#39;est pas qu&#39;un simple jeu ; c&#39;est un moyen de créer des liens, d&#39;élaborer des stratégies et de profiter du grand air, et j&#39;ai la chance d&#39;en apprécier les multiples facettes depuis près d&#39;un demi-siècle. Qu&#39;il s&#39;agisse de la précision du placement d&#39;une boule ou de la camaraderie sur le terrain, ma passion pour la pétanque reste intacte.</p><p><img src="'+e+'" alt="Patrik Wiik with friends"></p><p><em>Partager cette passion avec des amis, c&#39;est ce qui rend la pétanque si spéciale. Les innombrables heures passées sur le terrain, remplies de rires, de compétition amicale et d&#39;histoires partagées, tissent des liens qui durent toute une vie.</em></p><hr><h2 id="ma-mission" tabindex="-1">Ma mission <a class="header-anchor" href="#ma-mission" aria-label="Permalink to &quot;Ma mission&quot;">​</a></h2><p>La mission de la Pétanque Academy est d&#39;aider les joueurs d&#39;élite à libérer tout leur potentiel en travaillant sur l&#39;aspect mental, souvent négligé, qui distingue les bons joueurs des excellents joueurs.</p><p>Par le biais de ce site, je partage :</p><ul><li><strong>Cadres de jeu mental</strong> développés à partir de plusieurs décennies d&#39;expérience</li><li><strong>Outils et modèles pratiques</strong> pour la définition d&#39;objectifs et la formation</li><li><strong>Méthodologies d&#39;atelier</strong> pour instaurer un climat de sécurité psychologique</li><li><strong>Approches fondées sur des données probantes</strong> pour la performance sous pression</li></ul><p>Il ne s&#39;agit pas de coaching technique, mais de créer les bases mentales qui permettront à vos compétences techniques de briller au moment où cela compte le plus.</p><hr><h2 id="pourquoi-j-39-ai-cree-ce-site" tabindex="-1">Pourquoi j&#39;ai créé ce site <a class="header-anchor" href="#pourquoi-j-39-ai-cree-ce-site" aria-label="Permalink to &quot;Pourquoi j&amp;#39;ai créé ce site&quot;">​</a></h2><p>Après plus de 45 ans de pétanque, j&#39;ai vu d&#39;innombrables joueurs talentueux lutter non pas avec la technique, mais avec :</p><ul><li><strong>La voix intérieure critique</strong> qui détruit la confiance après les erreurs</li><li><strong>Pression</strong> qui les pousse à jouer différemment en compétition</li><li><strong>Manque de structure</strong> dans l&#39;entraînement mental</li><li><strong>Isolement</strong> dans leur parcours de développement</li></ul><p>Ce site a pour vocation de changer la donne. Chaque contenu y est conçu pour être immédiatement applicable : des modèles à copier, des cadres de travail utilisables dès aujourd’hui et des outils performants en compétition réelle.</p><hr>',17)),r(g),u[2]||(u[2]=n('<h2 id="contactez-nous" tabindex="-1">Contactez-nous <a class="header-anchor" href="#contactez-nous" aria-label="Permalink to &quot;Contactez-nous&quot;">​</a></h2><p>N&#39;hésitez pas à me contacter ! Que vous ayez des questions, souhaitiez partager votre expérience ou soyez intéressé(e) par des ateliers et des formations, je suis à votre disposition.</p><h3 id="coordonnees" tabindex="-1">Coordonnées <a class="header-anchor" href="#coordonnees" aria-label="Permalink to &quot;Coordonnées&quot;">​</a></h3><p><strong>Courriel :</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Facebook :</strong> <a href="https://www.facebook.com/patrik.wiik" target="_blank" rel="noreferrer">facebook.com/patrik.wiik</a></p><hr><h2 id="aidez-moi-a-ameliorer-ce-site" tabindex="-1">Aidez-moi à améliorer ce site <a class="header-anchor" href="#aidez-moi-a-ameliorer-ce-site" aria-label="Permalink to &quot;Aidez-moi à améliorer ce site&quot;">​</a></h2><p>Vos commentaires sont précieux ! Ce site évolue constamment en fonction des besoins réels des joueurs d&#39;élite.</p><h3 id="j-39-aimerais-avoir-votre-avis-sur" tabindex="-1">J&#39;aimerais avoir votre avis sur : <a class="header-anchor" href="#j-39-aimerais-avoir-votre-avis-sur" aria-label="Permalink to &quot;J&amp;#39;aimerais avoir votre avis sur :&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Qu&#39;est-ce qui vous serait le plus utile ?</p><ul><li><p><strong>Quel type de contenu aimeriez-vous voir davantage ?</strong></p><ul><li>Davantage de techniques de jeu mental ?</li><li>Des modèles plus pratiques ?</li><li>Des études de cas de joueurs d&#39;élite ?</li></ul></li><li><p><strong>Que manque-t-il au site ?</strong></p><ul><li>Sujets non abordés ?</li><li>Des outils que vous souhaiteriez voir exister ?</li><li>Des ressources que vous ne trouvez pas ?</li></ul></li><li><p><strong>Qu&#39;est-ce qui fonctionne bien ?</strong></p><ul><li>Quelles pages vous ont été les plus utiles ?</li><li>Quels outils avez-vous réellement utilisés ?</li><li>Qu&#39;est-ce qui a fait la plus grande différence pour vous ?</li></ul></li><li><p><strong>Comment puis-je l&#39;améliorer ?</strong></p><ul><li>Améliorations de la navigation ?</li><li>Organisation du contenu ?</li><li>D&#39;autres exemples ?</li><li>Différents formats ?</li></ul></li></ul></div><h3 id="envoyez-moi-vos-commentaires" tabindex="-1">Envoyez-moi vos commentaires <a class="header-anchor" href="#envoyez-moi-vos-commentaires" aria-label="Permalink to &quot;Envoyez-moi vos commentaires&quot;">​</a></h3><p><strong>Envoyez vos commentaires par courriel à :</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Suggestions pour l&#39;objet du message :</strong></p><ul><li>« Commentaires sur le site : [Votre sujet] »</li><li>&quot;Demande de contenu : [Ce dont vous avez besoin]&quot;</li><li>« Témoignage de réussite : [Comment cela a aidé] »</li><li>« Suggestion : [Votre idée] »</li></ul><p><strong>Ce qu&#39;il faut inclure :</strong></p><ul><li>Votre niveau/expérience actuel</li><li>Ce sur quoi vous travaillez</li><li>Commentaires ou demandes spécifiques</li><li>Des exemples de réussite utilisant le contenu</li></ul><hr><h2 id="ce-que-disent-les-autres" tabindex="-1">Ce que disent les autres <a class="header-anchor" href="#ce-que-disent-les-autres" aria-label="Permalink to &quot;Ce que disent les autres&quot;">​</a></h2><details class="details custom-block"><summary>Commentaires des joueurs d&#39;élite</summary><p>« Le contenu relatif à la préparation mentale a complètement transformé ma façon d&#39;aborder la compétition. Le concept de &quot;Inner Coach&quot; à lui seul justifiait la découverte de ce site. » — Champion régional, France</p><p>« Enfin quelqu&#39;un qui comprend que la technique n&#39;est pas le problème. La méthodologie de l&#39;atelier a offert à notre club une toute nouvelle façon de s&#39;entraîner. » — Joueur de l&#39;équipe nationale suédoise</p><p>« Le modèle d&#39;objectif et le modèle de journal sont exactement ce dont j&#39;avais besoin. Simples, pratiques et vraiment utilisables. » — Joueur du tournoi, Espagne</p></details><hr><h2 id="a-propos-du-contenu" tabindex="-1">À propos du contenu <a class="header-anchor" href="#a-propos-du-contenu" aria-label="Permalink to &quot;À propos du contenu&quot;">​</a></h2><p>Tout le contenu de ce site est :</p><ul><li><strong>Gratuit et accessible</strong> - Sans abonnement ni contenu caché</li><li><strong>Pratiques et exploitables</strong> - Des modèles que vous pouvez utiliser dès aujourd&#39;hui</li><li><strong>Fondé sur des preuves</strong> - S&#39;appuie sur la recherche en psychologie et plus de 45 ans d&#39;expérience</li><li><strong>Mise à jour continue</strong> - Du nouveau contenu est ajouté en fonction de vos commentaires</li></ul><hr><h2 id="confidentialite-et-cookies" tabindex="-1">Confidentialité et cookies <a class="header-anchor" href="#confidentialite-et-cookies" aria-label="Permalink to &quot;Confidentialité et cookies&quot;">​</a></h2><p>Ce site utilise Google AdSense pour financer son fonctionnement. En utilisant ce site, vous acceptez l&#39;utilisation de cookies par Google à des fins de personnalisation des annonces et d&#39;analyse.</p><p><strong>Nous respectons votre vie privée :</strong> Aucune donnée personnelle n&#39;est collectée au-delà des analyses standard.</p><ul><li>Pas de listes de diffusion ni de spam</li><li>Vos coordonnées ne servent qu&#39;à répondre à vos messages.</li></ul><hr><h2 id="se-connecter-et-partager" tabindex="-1">Se connecter et partager <a class="header-anchor" href="#se-connecter-et-partager" aria-label="Permalink to &quot;Se connecter et partager&quot;">​</a></h2><p>Si vous trouvez ce contenu utile :</p><ul><li><strong>Partagez-le</strong> avec vos partenaires d&#39;entraînement</li><li><strong>Recommandez-le</strong> à votre club</li><li><strong>Insérez un lien vers cette ressource</strong> depuis vos propres ressources</li><li><strong>Donnez votre avis</strong> pour contribuer à son amélioration</li></ul><p>Ensemble, nous pouvons élever le niveau mental du jeu de pétanque dans le monde entier.</p><hr>',34)),r(h),u[3]||(u[3]=t("p",null,[t("strong",null,"Merci de faire partie de l'Académie de Pétanque !")],-1)),u[4]||(u[4]=t("p",null,"— Patrik Wiik",-1))])}]]);export{u as __pageData,d as default};
